<?php
/**
 * Representative runtime checks for the uploaded plugin releases.
 * Run only on a disposable local WordPress database with all 20 plugins and
 * WooCommerce active. This resets license tables and creates sample content.
 * QUICKWOO_REVIEW_DISPOSABLE=1 wp eval-file tools/plugin-runtime-smoke.php
 */
if(wp_get_environment_type()!=='local'||getenv('QUICKWOO_REVIEW_DISPOSABLE')!=='1')throw new RuntimeException('Requires local WordPress and QUICKWOO_REVIEW_DISPOSABLE=1; this script resets license fixtures.');
ob_start();
wp_set_current_user(1);
$GLOBALS['review_results']=[];
function check($condition,$message){if(!$condition)throw new RuntimeException($message);}
function runcheck($name,$fn){global $review_results;try{$fn();$review_results[$name]='PASS';}catch(Throwable $e){$review_results[$name]='FAIL: '.$e->getMessage();}echo $name.': '.$review_results[$name]."\n";}
function call_private($object,$name,...$args){$m=new ReflectionMethod($object,$name);$m->setAccessible(true);return $m->invoke($object,...$args);}
$gates=['quick-accountant'=>'qacc_is_premium_active','quick-add'=>'qadd_is_premium_active','quick-audit'=>'qaud_is_premium_active','quick-code'=>'qcod_is_premium_active','quick-course-builder'=>'qcou_is_premium_active','quick-edit'=>'qedt_is_premium_active','quick-forms'=>'qfrm_is_premium_active','quick-images'=>'qimg_is_premium','quick-importer'=>'qiim_is_premium','quick-mail'=>'qmail_is_premium','quick-points'=>'qpnt_is_premium','quick-quotes'=>'qquo_is_premium_active','quick-schedule'=>'qsch_is_premium_active','quick-seo'=>'qseo_is_premium_active','quick-ship'=>'qship_is_premium','quick-site'=>'qsit_is_premium_active','quick-traffic'=>'qtrf_is_premium_active','quick-variations'=>'qvar_is_premium_active'];
global $wpdb;
$wpdb->query("DELETE FROM {$wpdb->prefix}quick_license_activations");$wpdb->query("DELETE FROM {$wpdb->prefix}quick_licenses");
runcheck('All 18 plugins deny Pro without a license',function()use($gates){foreach($gates as $slug=>$f)check(!$f(),$slug.' unexpectedly unlocked');});
$key=QLIC_License_Generator::generate_key();
$wpdb->insert($wpdb->prefix.'quick_licenses',['product_slug'=>'quick-woo-suite','license_key'=>$key,'customer_email'=>'review@example.test','activation_limit'=>1,'status'=>'active','created_at'=>current_time('mysql')]);
$activation=qlic_activate_license_key_for_products($key,['quick-add']);
runcheck('Quick License activates suite and all 18 Pro gates',function()use($activation,$gates){check(!empty($activation['valid']),json_encode($activation));foreach($gates as $slug=>$f)check($f(),$slug.' failed valid suite activation');});
runcheck('Quick License accepts lowercase keys, rejects expiry and respects bundle scope',function()use($wpdb,$key,$gates){
 check(QLIC_License_Generator::canonicalize(strtolower($key))===$key,'Lowercase key damaged');
 $table=$wpdb->prefix.'quick_licenses';
 foreach(['inventory-control'=>['quick-add','quick-edit','quick-variations','quick-images','quick-ship','quick-points'],'revenue-customer-operations'=>['quick-forms','quick-schedule','quick-importer','quick-quotes','quick-accountant','quick-mail'],'admin-control'=>['quick-site','quick-seo','quick-audit','quick-traffic','quick-code'],'education'=>['quick-course-builder'],'full-quickwoo-suite'=>array_keys($gates),'plus-desktop'=>array_keys($gates)] as $bundle=>$members){
  $wpdb->update($table,['product_slug'=>$bundle],['license_key'=>$key]);
  foreach($gates as $slug=>$f)check($f()===in_array($slug,$members,true),$bundle.' scope incorrect for '.$slug);
 }
 $wpdb->update($table,['expires_at'=>'2000-01-01 00:00:00'],['license_key'=>$key]);
 foreach($gates as $slug=>$f)check(!$f(),$slug.' accepts expired license');
 $wpdb->update($table,['product_slug'=>'full-quickwoo-suite','expires_at'=>null],['license_key'=>$key]);
});
$sku='review-'.bin2hex(random_bytes(6));$productId=0;
runcheck('Quick Add creates a WooCommerce product and rejects duplicate SKU',function()use($sku,&$productId){$row=['product_name'=>'Review product','sku'=>$sku,'regular_price'=>'20','stock_quantity'=>5];$r=QADD_Processor::create_products([$row]);check($r['success_count']===1,json_encode($r));$productId=wc_get_product_id_by_sku($sku);check($productId>0,'Product not persisted');check(!QADD_Processor::validate_rows([$row])[0]['valid'],'Duplicate SKU accepted');});
runcheck('Quick Edit updates stock',function()use(&$productId){$r=QEDT_Bulk::apply([$productId],'set_stock_quantity',['quantity'=>8]);check($r['success_count']===1,json_encode($r));check(wc_get_product($productId)->get_stock_quantity()===8,'Stock unchanged');});
runcheck('Quick Variations creates combinations and skips duplicates',function(){ $p=new WC_Product_Variable();$p->set_name('Review variable');$id=$p->save();$a=new QVAR_Admin();$block=['product_id'=>$id,'attributes'=>[['name'=>'Color','values'=>'Red,Blue']]];$r=call_private($a,'process_product_block',$block);check($r['created']===2,json_encode($r));$r=call_private($a,'process_product_block',$block);check($r['created']===0&&$r['skipped']===2,json_encode($r));});
runcheck('Quick Importer applies price fields and rejects duplicate SKU',function()use(&$productId,$sku){$s=new QIIM_Settings();$p=new QIIM_Products($s,new QIIM_Taxonomies($s));$r=$p->apply_product_fields($productId,['regular_price'=>'25.50']);check(!is_wp_error($r),'Import failed');check((float)get_post_meta($productId,'_regular_price',true)===25.5,'Price not saved');check(!$p->validate_unique_sku($sku,0),'Duplicate SKU accepted');});
runcheck('Quick Forms saves and renders required email field',function(){ $b=new QFRM_Builder();$id=$b->save_form(0,['name'=>'Review form','fields'=>[['name'=>'email','type'=>'email','label'=>'Your email','required'=>1]]]);check(!is_wp_error($id)&&$id>0,'Save failed');$html=do_shortcode('[quick_form id="'.$id.'"]');check(str_contains($html,'type="email"')&&str_contains($html,'required'),'Form not rendered');update_option('review_form_id',$id);});
runcheck('Quick Schedule renders booking form',function(){check(str_contains(do_shortcode('[quick_schedule_booking]'),'<form'),'Booking form missing');});
runcheck('Quick Quotes renders quote request form',function(){check(str_contains(do_shortcode('[quick_quote_form]'),'<form'),'Quote form missing');});
runcheck('Quick Course Builder grades correct and incorrect answers',function(){ $q=[['id'=>'a','correct_index'=>1],['id'=>'b','correct_index'=>0]];check(QCOU_Test_Grader::grade($q,['a'=>1,'b'=>0])===100,'Correct answers');check(QCOU_Test_Grader::grade($q,['a'=>0,'b'=>0])===50,'Incorrect answer');check(post_type_exists(QCOU_Constants::CPT_COURSE),'Course post type missing');$course=wp_insert_post(['post_type'=>QCOU_Constants::CPT_COURSE,'post_title'=>'Review course','post_status'=>'publish']);QCOU_Progress::mark_complete(1,$course,'intro');check(QCOU_Progress::is_module_complete(1,$course,'intro'),'Completion not saved');QCOU_Progress::mark_incomplete(1,$course,'intro');check(!QCOU_Progress::is_module_complete(1,$course,'intro'),'Completion not cleared');});
runcheck('Quick Points credits, debits and prevents negative balance',function(){ $t=new QPNT_Transactions(new QPNT_Settings());$before=$t->get_balance(1,false)['total_points'];check($t->add_points(1,20,'review')!==false,'Credit failed');check($t->get_balance(1,false)['total_points']===$before+20,'Credit balance');check($t->add_points(1,-10,'review')!==false,'Debit failed');check($t->add_points(1,-10000000,'review')===false,'Overdraft allowed');});
runcheck('Quick Accountant totals income and expenses',function()use($wpdb){$cat=(int)$wpdb->get_var('SELECT id FROM '.qacc_table_categories().' LIMIT 1');foreach([['income',100],['expense',25]] as [$type,$amount])$wpdb->insert(qacc_table_transactions(),['txn_date'=>gmdate('Y-m-d'),'amount'=>$amount,'txn_type'=>$type,'category_id'=>$cat,'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')]);$r=(new QACC_Reports())->get_dashboard_data();check($r['income']>=100&&$r['expenses']>=25&&$r['profit']===$r['income']-$r['expenses'],'Totals incorrect');});
runcheck('Quick Mail saves and renders a template',function(){$r=new QMAIL_Renderer();$t=new QMAIL_Templates(new QMAIL_Settings(),$r);$id=$t->save_template(['name'=>'Review mail','status'=>'publish','subject'=>'Hello {{name}}','html'=>'<p>Welcome {{name}}</p>']);check(!is_wp_error($id)&&$id>0,'Template save failed');$mail=$t->build_email_from_template_id($id,['name'=>'Sam']);check(str_contains(json_encode($mail),'Welcome Sam'),'Variable substitution failed');});
runcheck('Quick Ship configures domestic shipping zone and methods',function(){$w=new QSHIP_Wizard();$r=$w->apply_shipping_configuration(['domestic_enabled'=>1,'international_enabled'=>0,'flat_rate'=>8,'free_threshold'=>'100','country'=>'CA','local_pickup'=>1]);check(empty($r['errors'])&&count($r['messages'])===1,json_encode($r));$zones=WC_Shipping_Zones::get_zones();$matches=array_filter($zones,fn($z)=>$z['zone_name']==='Quick Ship Domestic');check(count($matches)===1,'Zone missing');$z=reset($matches);check(count($z['shipping_methods'])>=2,'Methods missing');$locations=(new WC_Shipping_Zone($z['zone_id']))->get_zone_locations();check(count($locations)===1&&$locations[0]->code==='CA'&&$locations[0]->type==='country','Canada destination not persisted');});
runcheck('Quick Images composes image with logo and watermark',function(){ $files=[];foreach([['base',500,500],['logo',80,40],['watermark',100,100]] as [$name,$w,$h]){$f='/tmp/review-'.$name.'.png';$im=imagecreatetruecolor($w,$h);imagefill($im,0,0,imagecolorallocate($im,100,50,20));imagepng($im,$f);imagedestroy($im);$files[]=$f;}$composed=call_private(new QIMG_Processor(),'compose_image',...$files);check(!is_wp_error($composed),'Image compose error');$im=$composed['resource'];check($im instanceof GdImage&&imagesx($im)===500&&imagesy($im)===500,'Composition failed');imagedestroy($im);});
runcheck('Quick Audit extracts page title and detects missing metadata',function(){ $p=call_private(new QAUD_Plugin(),'analyze_page',home_url('/'),200,'<html><head><title>Review page</title></head><body><h1>Hello</h1><p>Review text</p></body></html>',0,10.0);check($p['meta']['title']==='Review page','Title not extracted');check(count($p['issues'])>0,'Missing metadata undetected');});
runcheck('Quick SEO renders editable post metadata',function(){ $id=wp_insert_post(['post_title'=>'Review SEO','post_type'=>'post','post_status'=>'publish']);$_POST=['qseo_meta_box_nonce'=>wp_create_nonce('qseo_meta_box_nonce'),'_quickseo_seo_title'=>'Review custom title'];qseo_save_meta_box_data($id);check(get_post_meta($id,'_quickseo_seo_title',true)==='Review custom title','Metadata not saved');$_POST=[];ob_start();qseo_render_meta_box(get_post($id));$html=ob_get_clean();check(str_contains($html,'input')&&str_contains($html,'Review custom title'),'SEO controls missing');});
runcheck('Quick Code detects mobile and desktop targeting',function(){$_SERVER['HTTP_USER_AGENT']='Mozilla iPhone Mobile';check(QCOD_Conditions::detect_device()==='mobile','Mobile detection');$_SERVER['HTTP_USER_AGENT']='Mozilla Desktop';check(QCOD_Conditions::detect_device()==='desktop','Desktop detection');});
runcheck('Quick Site creates cache folders and clamps invalid TTL',function(){check(qsit_ensure_cache_dirs(),'Cache directories unavailable');$old=get_option(QUICK_SITE_OPTION_KEY);update_option(QUICK_SITE_OPTION_KEY,['cache_ttl'=>-1]);check(qsit_get_settings()['cache_ttl']===60,'Unsafe cache TTL');update_option(QUICK_SITE_OPTION_KEY,$old);});
runcheck('Quick Site bypasses page IDs and personal queries while allowing tracking parameters',function(){
 $user=get_current_user_id();$uri=$_SERVER['REQUEST_URI']??'/';wp_set_current_user(0);
 try{
  foreach(['/?page_id=7','/?p=7','/booking/?email=review@example.test','/?s=private'] as $test){$_SERVER['REQUEST_URI']=$test;check(!QSIT_Cache::is_cacheable_request(),'Unsafe shared cache: '.$test);}
  $_SERVER['REQUEST_URI']='/review-cache/?utm_source=review';check(QSIT_Cache::is_cacheable_request(),'Tracking query cannot use cache');
 }finally{$_SERVER['REQUEST_URI']=$uri;wp_set_current_user($user);}
});
runcheck('Quick Traffic categorizes devices and hashes visitors',function(){check(qtrf_detect_device('Mozilla iPhone Mobile')==='mobile','Device classification');$a=qtrf_get_visitor_hash('192.0.2.1','review');$b=qtrf_get_visitor_hash('192.0.2.1','review');check($a===$b&&!str_contains($a,'192.0.2.1'),'Visitor hash invalid');});
runcheck('Quick Connector health is public and plugin management requires authentication',function(){wp_set_current_user(0);$r=rest_do_request(new WP_REST_Request('GET','/quick/v1/health'));check($r->get_status()===200,'Health failed');$r=rest_do_request(new WP_REST_Request('GET','/quick/v1/plugins'));check($r->get_status()===401||$r->get_status()===403,'Anonymous plugin list exposed');wp_set_current_user(1);$r=rest_do_request(new WP_REST_Request('GET','/quick/v1/modules/catalog'));check($r->get_status()===200,'Operator catalog failed');});
// A dedicated anonymous test page for tools/test-plugin-forms.cjs.
$fixture_id=(int)get_option('quickwoo_review_forms_page');
$fixture=['post_type'=>'page','post_status'=>'publish','post_title'=>'QuickWoo review forms','post_name'=>'quickwoo-review-forms','post_content'=>'[quick_form id="'.(int)get_option('review_form_id').'"] [quick_quote_form] [quick_schedule_booking]'];
if($fixture_id){$fixture['ID']=$fixture_id;$fixture_id=wp_update_post($fixture,true);}else{$fixture_id=wp_insert_post($fixture,true);}
check(!is_wp_error($fixture_id)&&$fixture_id>0,'Could not create review page');
update_option('quickwoo_review_forms_page',$fixture_id);
$log=ob_get_clean();echo $log;
file_put_contents(getenv('QUICKWOO_REVIEW_RESULTS')?:'/tmp/quickwoo-runtime-results.json',json_encode($GLOBALS['review_results'],JSON_PRETTY_PRINT));
if(count(array_filter($GLOBALS['review_results'],fn($v)=>$v!=='PASS')))WP_CLI::error('Runtime checks failed.');
